// Lead sent by another flow (email auto-reply, site form, WhatsApp) or by hand
const b = $('New lead (webhook)').first().json.body ?? {};
const found = $('Find customer').all().map(i => i.json).find(c => c && c.id);
const created = $('Create customer').isExecuted ? $('Create customer').first().json : null;
const c = found || created;
if (!b.message) throw new Error('Lead without message: send at least "email" and "message"');
return [{ json: { customer_id: c.id, name: c.name, email: c.email, company: c.company || b.company || '', phone: c.phone || b.phone || '', source: b.source || c.source || 'email', message: String(b.message).trim() } }];

// Leads registered directly in Supabase (status = lead) with the message in "notes"
return $input.all().map(i => i.json).filter(c => c.id && (c.notes || '').trim()).map(c => ({ json: {
  customer_id: c.id, name: c.name, email: c.email, company: c.company || '', phone: c.phone || '', source: c.source || 'other', message: c.notes.trim() } }));

// Builds the prompt with the lead + the service catalog from Supabase
// Report language: 'pt', 'en' or 'es' (also change it in the "Read evaluation" node)
const REPORT_LANGUAGE = 'pt';
const LANG_NAME = { pt: 'português do Brasil', en: 'inglês (English)', es: 'espanhol (Español)' };
const services = $('Get services').all().map(i => i.json).filter(s => s.code);
const catalog = services.sort((a,b) => a.sort_order - b.sort_order)
  .map(s => `- ${s.code} ${s.name} (${s.category}): ${s.description} Ideal para: ${s.ideal_for || '-'}. Inclui: ${(s.features || []).join(', ')}`).join('\n');
const label = { email: 'e-mail', website: 'formulário do site', whatsapp: 'WhatsApp', referral: 'indicação', other: 'outro' };
const src = $('Lead from webhook').isExecuted ? $('Lead from webhook') : $('Leads with message');
return src.all().map(i => { const l = i.json; return { json: { ...l, prompt: [
  '# CATÁLOGO DA VIDAL TECHNOLOGIES', catalog,
  'Fora do catálogo: aplicativos nativos para lojas, logo e identidade visual, gestão de redes sociais e tráfego pago, suporte de TI.',
  '', '# LEAD',
  `Canal: ${label[l.source] || l.source}`, `Nome: ${l.name || '(não informado)'}`, `Empresa: ${l.company || '(não informada)'}`,
  `E-mail: ${l.email || '(não informado)'}`, `Telefone: ${l.phone || '(não informado)'}`, '', 'Mensagem:', l.message, '', `Idioma do relatório: ${LANG_NAME[REPORT_LANGUAGE] || LANG_NAME.pt}` ].join('\n') } }; });

// Reads Claude's JSON, maps it to the database enums and builds the email report
// Report language: 'pt', 'en' or 'es' (same as in the "Build prompt" node)
const REPORT_LANGUAGE = 'pt';
const T = {
  pt: { title: 'Avaliação de lead', noName: 'Lead sem nome', noCompany: 'empresa não informada', priority: 'Prioridade', h: ['Resumo do lead', 'Necessidades e problemas', 'Aderência às soluções', 'Prioridade sugerida', 'Informações que ainda faltam', 'Perguntas para a próxima conversa', 'Próximo passo recomendado'], original: 'Mensagem original', newLead: 'novo lead', lv: { 'Alta': 'Alta', 'Média': 'Média', 'Baixa': 'Baixa', 'Fora do catálogo': 'Fora do catálogo' }, src: { email: 'E-mail', website: 'Formulário do site', whatsapp: 'WhatsApp', referral: 'Indicação', other: 'Outro' } },
  en: { title: 'Lead evaluation', noName: 'Unnamed lead', noCompany: 'company not provided', priority: 'Priority', h: ['Lead summary', 'Needs and problems', 'Fit with our solutions', 'Suggested priority', 'Missing information', 'Questions for the next conversation', 'Recommended next step'], original: 'Original message', newLead: 'new lead', lv: { 'Alta': 'High', 'Média': 'Medium', 'Baixa': 'Low', 'Fora do catálogo': 'Out of scope' }, src: { email: 'Email', website: 'Website form', whatsapp: 'WhatsApp', referral: 'Referral', other: 'Other' } },
  es: { title: 'Evaluación de lead', noName: 'Lead sin nombre', noCompany: 'empresa no informada', priority: 'Prioridad', h: ['Resumen del lead', 'Necesidades y problemas', 'Adecuación a las soluciones', 'Prioridad sugerida', 'Información pendiente', 'Preguntas para la próxima conversación', 'Siguiente paso recomendado'], original: 'Mensaje original', newLead: 'nuevo lead', lv: { 'Alta': 'Alta', 'Média': 'Media', 'Baixa': 'Baja', 'Fora do catálogo': 'Fuera del catálogo' }, src: { email: 'Correo', website: 'Formulario del sitio', whatsapp: 'WhatsApp', referral: 'Recomendación', other: 'Otro' } },
}[REPORT_LANGUAGE];
if (!T) throw new Error('REPORT_LANGUAGE must be pt, en or es');
const leads = $('Build prompt').all().map(i => i.json);
const P = { 'Alta': 'high', 'Média': 'medium', 'Media': 'medium', 'Baixa': 'low' };
const F = { 'Alta': 'high', 'Média': 'medium', 'Media': 'medium', 'Baixa': 'low', 'Fora do catálogo': 'out_of_scope' };
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ul = a => '<ul>' + (a || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ul>';
const L = v => T.lv[v] || v;
const ol = a => '<ol>' + (a || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ol>';
return $input.all().map((item, idx) => {
  const lead = leads[idx];
  const raw = (item.json.text || '').trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  let ev; try { ev = JSON.parse(raw); } catch (e) { throw new Error('Claude did not return valid JSON: ' + raw.slice(0, 300)); }
  const score = Math.max(0, Math.min(100, Math.round(Number(ev.score) || 0)));
  const color = { high: '#1f9d55', medium: '#FBC105', low: '#888888' }[P[ev.priority]] || '#888888';
  const html = `<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#111">
 <div style="background:#000;background-image:linear-gradient(#000,#000);padding:18px 24px"><img src="https://vidaltechnologies.com.br/catalogo/logo-email.png" alt="vidal technologies" height="28" style="display:block;height:28px"><div style="color:#FBC105;font-size:13px;letter-spacing:.08em;text-transform:uppercase;margin-top:8px">${T.title}</div></div>
 <div style="padding:20px 24px;border:1px solid #eee;background:#fff">
  <p style="margin:0 0 6px"><b>${esc(lead.name || T.noName)}</b> · ${esc(lead.company || T.noCompany)} · ${esc(T.src[lead.source] || lead.source)}</p>
  <p style="margin:0 0 16px;color:#555">${esc(lead.email)} ${esc(lead.phone)}</p>
  <p style="display:inline-block;background:${color};color:#000;padding:6px 12px;border-radius:999px;font-weight:bold">${T.priority} ${esc(L(ev.priority))} · ${score}/100</p>
  <h3>1. ${T.h[0]}</h3><p>${esc(ev.summary)}</p>
  <h3>2. ${T.h[1]}</h3>${ul(ev.needs)}
  <h3>3. ${T.h[2]}</h3><p><b>${esc(L(ev.fit))}</b> · ${esc((ev.recommended_services || []).join(', '))}<br>${esc(ev.fit_reason)}</p>
  <h3>4. ${T.h[3]}</h3><p><b>${esc(L(ev.priority))} (${score}/100)</b> · ${esc(ev.score_breakdown)}<br>${esc(ev.priority_justification)}</p>
  <h3>5. ${T.h[4]}</h3>${ul(ev.missing_info)}
  <h3>6. ${T.h[5]}</h3>${ol(ev.next_questions)}
  <h3>7. ${T.h[6]}</h3><p><b>${esc(ev.next_step)}</b></p>
  <hr style="border:none;border-top:1px solid #eee"><p style="color:#888;font-size:12px">${T.original}:<br>${esc(lead.message).replace(/\n/g,'<br>')}</p>
 </div></div>`;
  return { json: { ...lead, ev, score, priority: P[ev.priority] || 'low', fit: F[ev.fit] || 'low',
    email_subject: `[Lead ${L(ev.priority)} · ${score}] ${lead.name || lead.email || T.newLead}`, email_html: html } };
});
